// Resolve the client scope from the webhook POST body.
// Reads clientId / clientCode from the incoming body; if neither is present the
// downstream query simply returns no rows (graceful no-op).
const body = $json;
const clientId = body && body.clientId ? body.clientId : null;
const clientCode = body && body.clientCode ? body.clientCode : null;
if (clientId || clientCode) {
  return { json: { clientId: clientId, clientCode: clientCode } };
}
return { json: { clientCode: null } };

// Build a single extraction prompt from all received Truth docs, then hand it
// to Ollama. Uses the ACTUAL document content, not just metadata.
const scope = $node['Resolve client scope'].json;
const clientCode = scope.clientCode;
const clientId = scope.clientId;
const docs = $('Load unparsed Truth docs').all().map(function(it){ return it.json; });
const list = docs.map(function(d){
  return '- doc[' + (d.import_key || '') + '] type=' + (d.documentType || '') +
  '\n  title=' + (d.title || '') + ' uri=' + (d.source_uri || '') +
  '\n  content: ' + (d.content || '(unavailable)');
}).join('\n');
const prompt =
  'You extract canonical facts from client-provided truth documents. ' +
  'Extract claims ONLY from the content shown below; do not invent facts absent from it.\n' +
  'Return STRICT JSON only, shape:\n' +
  '{"documents":[],' +
  '"entities":[{"entity_type","canonical_name","aliases":[]}],' +
  '"claims":[{"entity_name","field_key","claim_text","import_key"}]}\n' +
  'Every claim gets a deterministic import_key like "SYNTH-<dockey>-<n>".\n\n' +
  'DOCUMENTS:\n' + (list || '(none)') + '\n\nJSON: ';
return { json: { clientId: clientId, clientCode: clientCode, prompt: prompt } };

// Parse the Ollama JSON response into import_truth_pack() inputs.
// Strictness: a non-JSON / empty reply yields empty arrays (fail closed, no
// fabricated facts); the DB import still validates and raises exceptions.
const scope = $node['Resolve client scope'].json;
const clientCode = scope.clientCode;
const clientId = scope.clientId;
const raw = $json.response || '';
let data = {};
if (typeof raw === 'string') { try { data = JSON.parse(raw); } catch (e) { data = {}; } }
else if (raw && typeof raw === 'object') data = raw;
const docs = Array.isArray(data.documents) ? data.documents : [];

// Normalize entities: small models may echo the schema field names verbatim
// (e.g. entity_type='canonical_name') or put the real name in 'entity_name'.
const ents = Array.isArray(data.entities) ? data.entities : [];
const entities = [];
for (const e of ents) {
  if (!e || typeof e !== 'object' || e.claim) continue;
  const canonical = e.canonical_name || e.entity_name;
  if (!canonical) continue;
  const etype = (e.entity_type && e.entity_type !== 'canonical_name') ? e.entity_type : 'COMPANY';
  entities.push({
    entity_type: etype,
    canonical_name: canonical,
    aliases: Array.isArray(e.aliases) ? e.aliases : []
  });
}

// Attach an evidence_locator to each claim by matching the claim import_key
// prefix against the loaded truth docs.
const loaded = $('Load unparsed Truth docs').all().map(function(it){ return it.json; });
const claims = Array.isArray(data.claims) ? data.claims : [];
const claimsOut = claims.map(function(c){
  if (!c || typeof c !== 'object') return c;
  const ck = c.import_key || '';
  for (let i = 0; i < loaded.length; i++) {
    const d = loaded[i];
    const dk = d.import_key || '';
    if (dk && ck.indexOf(dk) === 0) {
      c.evidence_locator = {
        document_id: d.documentId,
        import_key: ck,
        section: null,
        source_uri: d.source_uri
      };
      break;
    }
  }
  return c;
});
return {
  json: {
    clientId: clientId,
    clientCode: clientCode,
    pDocs: JSON.stringify(docs),
    pEntities: JSON.stringify(entities),
    pClaims: JSON.stringify(claimsOut)
  }
};
